function validate([maze, ball, hole]) {
  if (!Array.isArray(maze) || maze.length < 1 || maze.length > 100) return 'maze needs 1 to 100 rows.';
  const cols = Array.isArray(maze[0]) ? maze[0].length : 0;
  if (cols < 1 || cols > 100) return 'maze needs 1 to 100 columns.';
  let empty = 0;
  for (const row of maze) {
    if (!Array.isArray(row) || row.length !== cols) return 'Every row of maze has the same length.';
    for (const cell of row) {
      if (cell !== 0 && cell !== 1) return 'Each cell is 0 (empty) or 1 (wall).';
      if (cell === 0) empty++;
    }
  }
  if (empty < 2) return 'The maze needs at least 2 empty cells.';
  for (const [name, point] of [['ball', ball], ['hole', hole]]) {
    if (!Array.isArray(point) || point.length !== 2 || !Number.isInteger(point[0]) || !Number.isInteger(point[1])) return `${name} is a [row, col] pair.`;
    if (point[0] < 0 || point[0] >= maze.length || point[1] < 0 || point[1] >= cols) return `${name} must be inside the maze.`;
    if (maze[point[0]][point[1]] !== 0) return `${name} must be on an empty cell.`;
  }
  if (ball[0] === hole[0] && ball[1] === hole[1]) return 'ball and hole must be at different cells.';
  return null;
}

