function findShortestWay(maze, ball, hole) {
  const rows = maze.length;
  const cols = maze[0].length;
  const moves = [['d', 1, 0], ['l', 0, -1], ['r', 0, 1], ['u', -1, 0]];
  const open = (r, c) => r >= 0 && r < rows && c >= 0 && c < cols && maze[r][c] === 0;
  const before = (a, b) => a[0] < b[0] || (a[0] === b[0] && a[1] < b[1]);
  const heap = [];
  const swap = (x, y) => { [heap[x], heap[y]] = [heap[y], heap[x]]; };
  const push = (entry) => {
    heap.push(entry);
    let child = heap.length - 1;
    while (child > 0 && before(heap[child], heap[(child - 1) >> 1])) {
      swap(child, (child - 1) >> 1);
      child = (child - 1) >> 1;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let parent = 0;
    for (;;) {
      const left = 2 * parent + 1;
      let next = parent;
      if (left < heap.length && before(heap[left], heap[next])) next = left;
      if (left + 1 < heap.length && before(heap[left + 1], heap[next])) next = left + 1;
      if (next === parent) return top;
      swap(parent, next);
      parent = next;
    }
  };
  const settled = new Set();
  push([0, '', ball[0], ball[1]]);
  while (heap.length > 0) {
    const [distance, path, row, col] = pop();
    if (row === hole[0] && col === hole[1]) return path;
    if (settled.has(row * cols + col)) continue;
    settled.add(row * cols + col);
    for (const [letter, dr, dc] of moves) {
      let r = row;
      let c = col;
      let steps = 0;
      while (open(r + dr, c + dc) && (r !== hole[0] || c !== hole[1])) {
        r += dr;
        c += dc;
        steps++;
      }
      if (steps > 0 && !settled.has(r * cols + c)) push([distance + steps, path + letter, r, c]);
    }
  }
  return 'impossible';
}

