function findShortestWay(maze, ball, hole) {
  // Bellman-Ford style: relax every stopping cell in every direction until nothing improves.
  const m = maze.length, n = maze[0].length;
  const best = maze.map(row => row.map(() => null));
  best[ball[0]][ball[1]] = [0, ''];
  const dirs = { u: [-1, 0], d: [1, 0], l: [0, -1], r: [0, 1] };
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
      if (!best[i][j] || (i === hole[0] && j === hole[1])) continue;
      for (const key of Object.keys(dirs)) {
        const [di, dj] = dirs[key];
        let x = i, y = j, d = 0;
        while (x + di >= 0 && x + di < m && y + dj >= 0 && y + dj < n && maze[x + di][y + dj] === 0) {
          x += di; y += dj; d++;
          if (x === hole[0] && y === hole[1]) break;
        }
        if (d === 0) continue;
        const candidate = [best[i][j][0] + d, best[i][j][1] + key], current = best[x][y];
        if (!current || candidate[0] < current[0] || (candidate[0] === current[0] && candidate[1] < current[1])) { best[x][y] = candidate; changed = true; }
      }
    }
  }
  return best[hole[0]][hole[1]] ? best[hole[0]][hole[1]][1] : 'impossible';
}

