function generate(rand, size) {
  for (;;) {
    const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 7);
    const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 7);
    const density = 0.1 + rand() * 0.3;
    const maze = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
    const empty = [];
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (maze[r][c] === 0) empty.push([r, c]);
    if (empty.length < 2) continue;
    const first = Math.floor(rand() * empty.length);
    let second = Math.floor(rand() * (empty.length - 1));
    if (second >= first) second++;
    return [maze, empty[first], empty[second]];
  }
}
